quests[36082] = { id = 36082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 068 - Lost Pendant" }
quests[36083] = { id = 36083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Gronn Eye", description = "This eye is proof of your strength at slaying ogron and your gladiator friend has born witness!\n\nTake the eye back to Limbflayer and claim your accolades!", completion = "A gronn's eye is not something they part with alive. Your gladiator described a fight hard won and this trophy is a testament to your abilities.  Well done!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36084] = { id = 36084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Botani Bloom", description = "This bloom is proof of your strength at slaying botani and your gladiator friend has born witness!\n\nTake the bloom back to Jonaa and claim your accolades!", completion = "The botani are nothing to be trifled with. They are incredibly cunning and their powers are strong on their home land. Taking one of their blooms is an true example of your fighting skill!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36085] = { id = 36085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Ebon Wings", description = "Now we bring our fight to the Adherents. Raastok is certain his new invention will give us control of the Apexis weapons, but we must get close - very close.\n\nKa'alu and her ravens will fly us to the Windswept Terrace. We shall gain a foothold there before pressing on to the Terrace of Dawn.", progress = "Quickly, we must not let this opportunity pass.", completion = "Good work!\n\nNow, it is time for the next phase of our plan.", objectives = "Slay 8 Adherents and Windkeeper Koreyx. Speak with Ka'alu for a ride to Windswept Terrace.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36086] = { id = 36086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Botani Bloom", description = "This bloom is proof of your strength at slaying botani and your gladiator friend has born witness!\n\nTake the bloom back to Limbflayer and claim your accolades!", completion = "The botani are nothing to be trifled with. They are incredibly cunning and their powers are strong on their home land. Taking one of their blooms is an true example of your fighting skill!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
