quests[36089] = { id = 36089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 070 - Abu'Gar's Reel" }
quests[36090] = { id = 36090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Orc Thorn", description = "This thorn is proof of your strength at slaying the infested and your gladiator friend has born witness!\n\nTake the thorn back to Jonaa and claim your accolades!", completion = "The infested appear to be mere husks animated by plant life. They are slow but very strong. Slaying even one is a strong demonstration of your own skill!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36091] = { id = 36091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Orc Thorn", description = "This thorn is proof of your strength at slaying the infested and your gladiator friend has born witness!\n\nTake the thorn back to Limbflayer and claim your accolades!", completion = "Sometimes we don't get turned into mulch for the jungle.  Sometimes we get back up, filled with plants. The Infested are hard to kill. Slaying even one is a strong demonstration of your own skill!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36092] = { id = 36092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Ancient Branch", description = "This branch is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the branch back to Jonaa and claim your accolades!", completion = "Ancients here tend to be guardians and tenders, but that does not make them any less dangerous. An enraged ancient is something to be behold. Taking a branch from one is a worthy deed!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36094] = { id = 36094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Ancient Branch", description = "This branch is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the branch back to Limbflayer and claim your accolades!", completion = "Ancients here tend to be guardians and tenders, but that does not make them any less dangerous. An enraged ancient is something to be behold. Taking a branch from one is a worthy deed!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36095] = { id = 36095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azuka Bladefury", description = "Agent Springslip is dead. A fire smolders inside a large wound where his heart used to be.\n\nFlipping through a report you find on his corpse you are able to piece together some basic information. Azuka has betrayed the ogres, she has killed Ugbright and taken his power for herself.\n\nYou should report this information to Bodrick at once.", sourceObjective = "Return to Bodrick Grey at your garrison in Shadowmoon Valley.", completion = "I'm sorry to hear Springslip didn't make it. He was a good agent.\n\nThis news of Azuka gaining even more power is troubling to say the least.", sourceObjectiveStatus = "unverified-source-field" }
quests[36096] = { id = 36096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Ravager Claw", description = "This claw is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the claw back to Jonaa and claim your accolades!", completion = "Even the insects of Gorgrond are larger and meaner than other parts of the world I have been to! Killing them, which you have obviously done, takes a great deal of strength and skill.", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36097] = { id = 36097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Ravager Claw", description = "This claw is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the claw back to Limbflayer and claim your accolades!", completion = "Even the insects of Gorgrond are larger and meaner than other parts of the world I have been to! Killing them, which you have obviously done, takes a great deal of strength and skill.", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36098] = { id = 36098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Wasp Stinger", description = "This stinger is proof of your strength at slaying ancients and your gladiator friend has born witness!\n\nTake the stinger back to Jonaa and claim your accolades!", completion = "As you can see, the venom Gorgrond wasps have is extremely powerful. To face one is to possibly face your own death. I would refrain from harvesting more of these, one enough to prove your strength here!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
