quests[36103] = { id = 36103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Basilisk Scale", description = "This scale is proof of your strength at slaying basilisks and your gladiator friend has born witness!\n\nTake the scale back to Jonaa and claim your accolades!", completion = "A gruesome trophy from a gruesome beast. To be frozen and eaten slowly is not a death I would choose. The world is better with less of these basilisks in it!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
