quests[36105] = { id = 36105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Elemental Crystal", description = "This crystal is proof of your strength at slaying elementals and your gladiator friend has born witness!\n\nTake the crystal back to Jonaa and claim your accolades!", completion = "I have seen no elementals elsewhere in Draenor that compare in ferocity to those in Gorgrond. I wonder what caused them to be so angry. That crystal was hard-won I am sure!", objectives = "Take the proof to Rangari Jonaa at Highpass in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36106] = { id = 36106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proof of Strength: Elemental Crystal", description = "This crystal is proof of your strength at slaying elementals and your gladiator friend has born witness!\n\nTake the crystal back to Limbflayer and claim your accolades!", completion = "I have seen no elementals elsewhere in Draenor that compare in ferocity to those in Gorgrond. I wonder what caused them to be so angry. That crystal was hard-won I am sure!", objectives = "Take the proof to Limbflayer at Beastwatch in Gorgrond.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36107] = { id = 36107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophy Hunter of Gorgrond", objectives = "I believe I speak for all of us when I say you are among the fiercest predators in Gorgrond! You have faced and slain Gorgrond's most dangerous creatures on their home ground and lived to bring something of them back here.\n\nThe gladiators have come together found something that will show the world your might! Bask in the glory champion!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
