quests[36116] = { id = 36116, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 061 - Bag of Herbs" }
quests[36117] = { id = 36117, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Broken Precipice", description = "Hey there! You're the commander of this keep, right? I represent the Steamwheedle Preservation Society.\n\nWe've been trying to get a very important excavation up and running in Nagrand. Unfortunately, we've had trouble with ogres in the area.\n\nIn fact, one of our best preservationists recently went missing while surveying the area. He's the third society member we've lost up there this week!\n\nWe aren't really equipped for a rescue mission... so whad'ya say? We could really use the help.", completion = "You're looking for what now? I mean, yeah sure... whatever. Just get me down alright?", objectives = "Find Greblin Fastfizzle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36118] = { id = 36118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Pile of Rubble" }
quests[36119] = { id = 36119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Ashran", description = "Greetings, and welcome to Ashran. \n\nReport to Commander Anne Dunworthy in Stormshield for your briefing.", completion = "You've just now showed up? Well, better late than never.", objectives = "Speak to Commander Anne Dunworthy in Stormshield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36123] = { id = 36123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Wilderness", description = "The Road of Glory is not just the only field of strife in this land, {name}. We must go into the wilderness here to uncover the artifacts.\n\nVenture forth and kill a member of the Horde you find in the outskirt areas and bring me back a piece of their armor to prove your worth.", progress = "That was fast, did you bring me a piece of their armor as proof?", completion = "Fantastic. You can always bring me back tokens you find on Horde corpses for a bonus reward.", objectives = "Chris Clarkie in Stormshield Stronghold wants you to kill a member of the Horde outside of the main road and recover a piece of their armor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36125] = { id = 36125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road of Glory", description = "The Horde intends to force us out of Ashran, {name}. We can't let them succeed. March into the Road of Glory and thin their ranks by at least five.", completion = "Nice work, {name}. You're a natural.", objectives = "Chris Clarkie in Stormshield wants you to kill 5 members of the Horde within the Road of Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36127] = { id = 36127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Ashran", description = "As a Farseer, I can peer into the far corners of Ashran while within Stormshield. But you must go forth and see it for yourself, {name}.", completion = "I can see you have the spirit of a true adventurer, {name}. Come visit me anytime and you can see Ashran through my eyes, even from Stormshield.", objectives = "Farseer Kylanda in Stormshield wants you to explore The Road of Glory, The Molten Quarry, Brute's Rise, The Amphitheater Of Annihilation and The Ashmaul Burial Grounds in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36128] = { id = 36128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabermaw - Saberon Vignette Boss" }
quests[36129] = { id = 36129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Nas Dunberlin" }
quests[36130] = { id = 36130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reporting For Duty", description = "Front and center, {name}! No time to waste, go speak with these fellows and they'll fill you in.", completion = "Yes yes, it's the real Harrison Jones. Why is he such a celebrity all of a sudden?", objectives = "Speak to Misirin Stouttoe, Farseer Kylanda and Chris Clarkie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36131] = { id = 36131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Worth", description = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the icespine stingers you brought me. Use it to catch the Zangar eels in these coastal waters.", progress = "Catch those eels?", completion = "I see you are both a fisherman and a warrior.  I will do what I can to help you.", objectives = "Prove your worth to Mokugg Lagerpounder by catching 5 Zangar Eels using the supplied bait.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36132] = { id = 36132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglin' In Our Garrison", description = "You have proven your worth, traveler.  Now take this frostwolf fishing journal back to your garrison and study up.  You will be catching all you can eat in no time.", progress = "We can use that as bait?!", completion = "Look at all the bait ideas in this thing! Great job {name}!", objectives = "Return to Mak'jin with the Frostwolf Fishing Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36133] = { id = 36133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran. Go out and kill any you find and bring at least five to Ecilam the Mage near the campfire in Stormshield Stronghold.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort.", objectives = "Misirin Stouttoe in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 5 Artifact Fragments to Ecilam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36134] = { id = 36134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Awakening", description = "We've tracked Warlord Bladefury and the stolen artifact to the salt fields of western Gorgrond.\n\nThisalee Crow will meet you there with an advance scouting team.\n\nThe entire garrison is on high alert. We must be ready to intercept the enemy if necessary.", progress = "This isn't looking good.", completion = "I've never seen a magnaron of that size before. This is bad, {name}.", objectives = "Speak to Thisalee Crow at Gorgorek's Rest in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36135] = { id = 36135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rosa is bad", description = "Text", objectives = "Retrieve Rulga's lost inscription papers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36136] = { id = 36136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Awakening", description = "We've tracked Warlord Bladefury an' da stolen artifact ta northern Gorgrond.\n\nCholuna be dere wit a scouting team.\n\nI got dey entire garrison on high alert. Go, meet wit her, and intercept da enemy if necessary.", completion = "I've never seen a magnaron of that size before. This is bad, {name}.", objectives = "Speak to Choluna at Gorgorek's Rest in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36137] = { id = 36137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easing into Lumberjacking", description = "<Sir/Ma'am>, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work.\n\nWhile I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree an able-bodied lazy-good-for-nothing peon will come and chop it down and give you the timber.\n\nFrostfire isn't the best place for timber, but I did see a suitable small tree nearby.", progress = "This garrison isn't going to build itself, commander! We need timber!", completion = "You're going to make a fine overseer, sir! Keep those peons in line!\n\nNow you know the basics of logging and finding timber. Time to put them to good use for the good of your garrison.", objectives = "Harvest a Timber Sample from Small Timber and return it to Lumber Lord Oktron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36138] = { id = 36138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Timber into Profit", description = "Now that you know how to put peons to work harvesting timber, we're going to create a work order for your mill.\n\nBut first we're going to need some timber to process!\n\nAll around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order.\n\nAnd as usual, let the peons do the hard work. Just keep 'em protected. Draenor's a dangerous place!", progress = "We need lots and lots of timber, commander!", completion = "That's how it's done, commander!\n\nWe're now fully operational. Any time you have enough timber to place a work order, come on back to me and we'll get started.\n\nThis garrison ain't gonna build itself!", objectives = "Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36139] = { id = 36139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Pandaria - Dungeon Normal Nth" }
quests[36140] = { id = 36140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pandaria 88-90" }
quests[36141] = { id = 36141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icespine Stingers", description = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior.\n\nThe canyon north of us is full of icespine stingers.  Slaughter them and bring their stingers back to me.  They should work well as bait in these local waters.", progress = "Have those stingers for me?", completion = "Not bad traveler, not bad at all.", objectives = "Prove your worth to Mokugg Lagerpounder by collecting 4 Icespine Stingers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36142] = { id = 36142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharper Blades, Bigger Timber", description = "Incredible news, Commander {name}. Your ever-loyal servant (that's me) has managed to secure us timber lords. Now maybe you don't know what a timber lord is, so let explain: think of a blood-crazed, mass murderer who enjoys nothing more than killing. Now take that same enthusiasm for killing and apply it to killing trees! That's a timber lord.\n\nWhat this means is that we can now cut medium sized timber - but first we need to give these timber lords a test run.\n\nThere's a suitable tree nearby. Good luck!", progress = "Did you harvest that timber sample yet?", completion = "You didn't believe me about those timber lords, did you? Well now you know.\n\nIt looks like this group will serve you well, sir. Medium sized trees across Draenor are now at your mercy. That means more timber per tree!", objectives = "Harvest a Timber Sample from Timber and return it to Lumber Lord Oktron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36143] = { id = 36143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Lich King - Dungeon Normal 1st" }
