quests[36151] = { id = 36151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Cataclysm - Dungeon Normal Nth" }
quests[36152] = { id = 36152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cataclysm 84-85" }
quests[36157] = { id = 36157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires of the Betrayer", description = "I have much to ask of you, {name}, but before we begin I must ensure that you develop yourself to your full potential. I can help.\n\nI'd like to create a link between us, an artifact that will enhance your power and allow me to track your progress. How do you feel about amulets? No? A ring? I've got it.\n\nMy contacts among the arakkoa outcasts tell of a band of pure solium. Right now it's in the talons of High Sage Viryx high atop Skyreach. Bring me that ring, {name} - you and I have much better uses for it.", progress = "The arakkoa we see today are a shade of their former glory. They hide atop their spires and glower at the land below, smug and superior. The truth is that they were driven to their lofty perches by the very enemies they look down on today.\n\nI wish the arakkoa were easier to deal with. Their manipulation of the sun's rays could've been an asset to us.", completion = "The ring! You've got it. Feel how it's still warm to the touch? The power of Draenor's sun is locked into the metal. This is perfect, {name}. It is exactly the base material we need to fashion into something amazing.\n\nWhile I prepare your treasure, let's talk about our next steps...", objectives = "Collect a Pure Solium Band from High Sage Viryx in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36158] = { id = 36158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Draenor's Secret Power", description = "Since we're going to be working so closely together, I'd like to upgrade that ring of yours. Ancient magics are the key: apexis crystals, the leftover remains of an earlier arakkoa civilization! They can be found among the most dangerous creatures around the world.\n\nCollect 4986 crystals for me.\n\nDon't look at me like that. I'm a mage. I did the math. I need exactly 4986 crystals. 4985 is inadequate. 4987 is of course absurd.\n\nFour thousand, nine hundred eighty-six. Go!", progress = "Do you have the crystals? I hope you kept an accurate count. If you counted wrong I simply can't be held responsible for the consequences.", completion = "Marvelous, marvelous! I will use these to upgrade your ring once we finish up a couple more tasks...", objectives = "Gather 4986 Apexis Crystals for Archmage Khadgar. Crystals can be found amongst creatures in the most dangerous parts of the world.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36159] = { id = 36159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss 004 - Graveltooth" }
quests[36160] = { id = 36160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Every Rose Has Its Thorn", description = "These feelings are too strong. I can no longer hide my love away.\n\nI need to tell Thorn the truth. I need to tell Thorn, I love her.\n\nShe mentioned her favorite flower is a rose.  I've been so heads down with my work... I don't even know where I could find a rose on Draenor.", progress = "We are under attack!", completion = "Commander! The Burning Blade attacked just a few moments ago, they are looking for the Heart of Gorgorek. \n\nThankfully, Lieutenant Thorn was here to protect us.\n\nWhat? You found a rose? Shh, hand it to me quickly. I'll hold onto this until the time to confess my love is right.", objectives = "Find Baros a rose for Thorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36161] = { id = 36161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There Is Smoke...", description = "Burning Blade assassins have infiltrated the garrison. We must not let them take the Heart of Gorgorek, commander.", completion = "The assassin appeared out of nowhere.\n\nBaros took the blade that was meant for my heart. I ripped out the throat of our attacker... but I was too late.\n\nBaros gave me this flower before he passed.\n\n<Thorn holds up the rose. A tear rolls down her cheek.>", objectives = "Kill Rag'sla Thunkblade, Akatha Blazeburn, and Drek the Firecaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36162] = { id = 36162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stolen Heart", description = "Don't let Azuka take the heart, commander. Don't let her win.", completion = "Today was not a good day.", objectives = "Kill Azuka Bladefury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36163] = { id = 36163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Exarch's Call", description = "Ahhh, just the {race} I were hopin' ta see, my dear.\n\nYrel stopped by the garrison earlier lookin' fer ya. Such a lovely lass, that one! Asked me all about ma family back home when I be feelin' homesick. Bless her. Anyway, what were I goin' on about ag'in?\n\nOh! She asked if ye'd meet her at Elodor to the east.\n\nShe's been invited by the draenei council ta face the Exarch trials, whatever those may be.\n\nAnyway, ye'd better scooch!", completion = "Thank you for coming, {name}.", objectives = "Speak to Yrel at Elodor in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36164] = { id = 36164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Courage", description = "An Exarch must be a pillar of strength, and no greater strength is there than the courage to face danger.\n\nFar to the northwest, among the snowy crags of Frostfire Ridge, lives a primal fury named Everburn.\n\nOnly when you face one of these creatures eye to eye, will you know the extent of your courage.", completion = "I see that you and Yrel have stared into the eyes of the most primal of the elementals, and not waivered from your path.\n\nIt pleases me to say that your courage is not lacking.\n\nWell done.", objectives = "Kill Everburn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36165] = { id = 36165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time to Waste", description = "We're in luck, commander. The antidote is relatively easy tae make.\n\nI've made a small amount with what I had on me. You should take it tae Kolrigg before it's too late. It'll keep him alive long enough for me tae make more.", progress = "<Kolrigg grumbles incoherently.>", completion = "By Muradin's beard... what a headache...", objectives = "Administer the Spiresalve to Kolrigg Stoktron in Southport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36166] = { id = 36166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time to Waste", description = "Commander, we're in luck. The antidote recipe is fairly simple.\n\nI was able to make a small amount with what I had on me. You should take it to Lunzul before it's too late. It should keep her alive long enough for me to make more.", progress = "<Lunzul grumbles incoherently.>", completion = "By da spirits... me head be hurtin'...", objectives = "Administer the Spiresalve to Lunzul in Axefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36167] = { id = 36167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Heart", description = "The Trial of Heart is a test of your willingness to persevere in the face of great adversity.\n\nFar to the west, there is a rangari outpost at Cerulean Lagoon.\n\nThey have sent a request for help. Some sort of infection is making everyone in the area sick. They desperately need aid.\n\nGo and seek out the rangari stationed there. Help them find the cause of this terrible ailment.", completion = "News of your deeds precedes you. Rangari Saardar already sent word of your excellent work.\n\nThanks to the both of you, {name}.", objectives = "Speak to Yrel at Cerulean Lagoon, then find out the cause of the poisonous mist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36168] = { id = 36168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Faith", description = "No Exarch trial is complete without a holy pilgrimage to the sacred resting place of our fallen champions.\n\nOn the way, I ask that you take Vindicator Maraad's ashes and lay them to rest within the hallowed halls of Auchindoun.\n\nThere, the spirits of our fallen ancestors will test Yrel's greatest weakness.\n\nGood luck.", completion = "It seems you have been successful in your journey.\n\nHow do I know this? If you had not passed the challenge of the ancestors, you would not have returned at all.", objectives = "Speak to Soulbinder Tuulani outside the entrance to Auchindoun, then pass the Trial of Faith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36169] = { id = 36169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Trial of Champions", description = "The first three trials you have passed with flying colors.\n\nFor the final trial, you shall face the Exarch Council.\n\nSpeak to me when you are ready to begin.", completion = "Well done, champion. Well done.", objectives = "Defeat the Exarch Council.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36170] = { id = 36170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Femur of Improbability" }
quests[36171] = { id = 36171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botani Invasion!", description = "The plants seem different today. Grass blades bend against the wind and catch on my boots. Twice this morning a tree branch struck my helmet as it fell.", progress = "We must hold the line!", completion = "We beat back nature, Commander. May I be excused? I'd like to get all this sap out of my armor.", objectives = "Repel the botani invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36174] = { id = 36174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 081 - Bounty of the Elements" }
quests[36176] = { id = 36176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Call for Huntsman", description = "<The note is barely legible, but it seems to be an advertisement for a local hunting competition out of Embaari Village.>\n\n\"Any and all competitors are welcome to test their skills in a friendly hunting challenge.\"", completion = "Another competitor for the competition? How wonderful! Garaal will be pleased!", objectives = "Deliver the Dirty Note to Fanara in Embaari Village to join the competition.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36177] = { id = 36177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Friendly Competition", description = "So you wish to join the competition, {name}? Best of luck to you.\n\nBe the first to gather a sack full of hides and talons from local wildlife and return them to me before the other competitors!\n\nWinner earns the opportunity for an apprenticeship under craftsman Garaal.\n\nGood luck!", progress = "The satchel is full and ready for delivery.", completion = "Congratulations, {name}! You did it!\n\nThe other competitors are nowhere to be found!\n\nGaraal will be most pleased. With such an abundance of supplies to work with he and the other craftsmen will have no trouble staying busy.\n\nI'll start tanning these immediately. They'll be ready for delivery in just a moment.", objectives = "Gather 4 Shadowmoon Hides and 3 Silverwing Talons and return to Fanara before the other competitors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36178] = { id = 36178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Mandrakor the Night Hunter" }
quests[36179] = { id = 36179, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwanted Pests", description = "Those creatures out in the shallows keep busting the turrets as fast as we can get them operational.\n\nI'm supposed to go clear them out but my blaster is completely busted; the damn thing barely can light a candle like this!\n\nCould you do me a favor and go kill a few of those pests while I get my blaster fixed at the shop?\n\nJust let Gazwitz know you covered for me so I can get reimbursed for the repair.", completion = "Lemmy's gun broke down again I take it?\n\nGood job covering for 'em out there. I could use more workers like you!", objectives = "Kill 10 Spore Drifters or Fungal Hulks in Sporemist Shallows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36182] = { id = 36182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tree-i-cide", description = "Commander, the goblins have brought you a present. They call it the Tree Murderer 9000.\n\nWhat's it do? I reckon it murders trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot!\n\nThere's a large piece of timber ready to be murdered nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", progress = "Did you harvest that timber sample yet?", completion = "This is fantastic! This sample indicates massive timber reserves in the large timber found across Draenor. And now with the Tree Murderer 9000 at your disposal you'll be able to chop those towering monstrosities down with ease.", objectives = "Harvest a Timber Sample from Large Timber and return it to Lumber Lord Oktron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36183] = { id = 36183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor", description = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself.\n\nWe never heard from him again, but we have our orders.\n\nPlease... please find him. He went towards the farm.", completion = "From one commander to another... thank you.\n\nWe've faced off on the field of battle so many times. Vashj'ir... the Jade Forest... Lion's Landing...\n\nI am glad I could end my journey with such a worthy adversary.", objectives = "Find Admiral Taylor at Admiral Taylor's Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36184] = { id = 36184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mother Lode" }
quests[36185] = { id = 36185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fair Trade", description = "Alright. Here you go.\n\nBe sure to deliver them to Garaal quickly. He has a heavy interest in detail and fine craftsmanship. He'll surely appreciate your work.", completion = "Greetings, {name}.\n\nFanara mentioned the competition was fierce this year.\n\nMy, my. These goods should keep me busy for an entire season!\n\nAs the victor of the competition one usually becomes my apprentice, however, your skills are surely in need of no apprenticeship.\n\nPerhaps a trade is in order.\n\nI'll keep your delivery and share the goods with our local craftsmen and in return, I'll share some of our knowledge with you.", objectives = "Garaal awaits your delivery.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36186] = { id = 36186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Greldrok the Cunning" }
quests[36188] = { id = 36188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moving On Up", description = "A generous decision, {name}.\n\nYou have demonstrated your skills as a hunter, delivered a piece worthy of your name and proven your dedication to your craft. Please, take this as a token of my gratitude.\n\nMay the light guide your hand and passion, your heart.", sourceObjective = "Garaal has offered to further your knowledge in leatherworking.", sourceObjectiveStatus = "unverified-source-field" }
quests[36189] = { id = 36189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Easing into Lumberjacking", description = "<Sir/Ma'am>, we're going to need a lot of lumber if we're going to build this garrison into a suitable fortress. That means we're going to have to do a little work.\n\nWhile I certainly wouldn't ask you to dirty your hands with manual labor, I do need you to go out and find timber for our mill. Once you mark a tree a lumberjack will come chop it down and give you the timber.\n\nLet's give our lumberjacks a test run. There's a tree nearby!", progress = "This garrison isn't going to build itself, commander! We need timber!", completion = "You're going to make a fine overseer, sir! Keep those lumberjacks in line!\n\nNow you know the basics of logging and finding timber. Time to put them to good use for the good of your garrison.", objectives = "Harvest a Timber Sample from Small Timber and return it to Justin Timberlord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36192] = { id = 36192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Timber into Profit", description = "Now that you know how to put lumberjacks to work harvesting timber, we're going to create a work order for your mill.\n\nBut first we're going to need some timber to process!\n\nAll around Draenor are juicy trees ripe for the chopping. Go out and find suitable timber for the lumber mill. Come back here when you have enough and we'll get started on a work order.\n\nAnd as usual, let the lumberjacks do the hard work. Just keep 'em protected. Draenor's a dangerous place!", progress = "We need lots and lots of timber, commander!", completion = "That's how it's done, commander!\n\nWe're now fully operational. Any time you have enough timber to place a work order, come on back to me and we'll get started.\n\nThis garrison ain't gonna build itself!", objectives = "Collect 10 pieces of Timber from around Draenor and then Place a Work Order at your Garrison's Lumber Mill.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36193] = { id = 36193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Act of Kindness", description = "I know that you and Vindicator Yrel are here on important matters, but I must ask you a favor.\n\nA squad of rangari left on patrol just before the poisonous mist set in.\n\nIf they were caught out in the swamp, they are surely in trouble.\n\nHarvest the Restorative Goldcaps growing among the reeds, and use them to restore any fallen rangari that you find.\n\nIf you find yourself in trouble, eat one to combat the poison.", progress = "Were you able to find the others?", completion = "Thank the Light! All of the rangari who were missing have returned accounted for. Thank you, hero.", objectives = "Use Restorative Goldcaps to revive fallen rangari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36194] = { id = 36194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sharper Blades, Bigger Timber", description = "Incredible news, Commander {name}. Your ever-loyal servant has managed to secure us commandojacks. Now maybe you don't know what a commandojack is, so let me explain: they're like lumberjacks, only highly trained in the art of killing. Mostly they're out of work mercenaries and assassins.\n\nWhat this means is that we can now cut medium sized timber - but first we need to give these commandojacks a test run.\n\nThere's a suitable tree nearby. Good luck!", progress = "Did you harvest that timber sample yet?", completion = "We haven't even scratched the surface when it comes to overkill.\n\nIt looks like this group will serve you well, sir. Medium sized trees across Draenor are now at your mercy. That means more timber per tree!", objectives = "Harvest a Timber Sample from Timber and return it to Justin Timberlord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36195] = { id = 36195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tree-i-cide", description = "Commander, your engineers have brought you a present. They call it the Wood Annihilator XXI the Third, Jr.\n\nWhat's it do? I reckon it annihilates trees - but more importantly it will allow for the harvesting of large timber. Do you know how much timber a large tree holds? Me neither, but I bet it's a lot!\n\nThere's a large piece of timber ready to be annihilated nearby. Why don't you give the contraption a test run? Bring me back whatever it harvests and I'll put it to good use.", progress = "Did you harvest that timber sample yet?", completion = "This is fantastic! This sample indicates massive timber reserves in the large timber found across Draenor. And now with the Wood Annihilator XXI the Third, Jr. at your disposal you'll be able to chop those towering monstrosities down with ease.\n\nGet off my back, I didn't name it.", objectives = "Harvest a Timber Sample from Large Timber and return it to Justin Timberlord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36196] = { id = 36196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Ashran", description = "Greetings, and welcome to Ashran. \n\nReport to General Ushet Wolfbarger in Warspear for your orders.", completion = "You've just now showed up? Well, better late than never.", objectives = "Speak to General Ushet Wolfbarger  in Warspear.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36197] = { id = 36197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reporting For Duty", description = "Front and center, {name}! No time to waste, go speak with these fellows and they'll fill you in.", completion = "Yea, that Zurge really is angry isn't he?", objectives = "Speak to Cymre Brightblade, Mare Wildrunner and Zurge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36198] = { id = 36198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uncovering the Artifact Fragments", description = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran.\n\nGo out and kill any you find and bring at least five Artifact Fragments to Fura the Mage in Warspear Outpost.", progress = "Are those Artifact Fragments, I see?", completion = "Good work. If you happen to find anymore Artifact Fragments, bring them to me or the others in need of them to contribute to the war effort.", objectives = "Cymre Brightblade in Warspear Outpost wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 5 Artifact Fragments to Fura.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36199] = { id = 36199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonshell Claws", description = "I will help you, but you are going to need to prove to me that you are not only a worthy fisherman, but also a fearless warrior.\n\nThe beach southeast of us is full of moonshell crawlers.  Slaughter them and bring their claws back to me.  They should work well as bait in these local waters.", progress = "Have those claws for me?", completion = "Not bad traveler, not bad at all.", objectives = "Prove your worth to Madari by collecting 4 Moonshell Claws.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36201] = { id = 36201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Worth", description = "Now that you have proven yourself as a warrior, let's see how your fishing skills hold up. I have fashioned a bait out of the moonshell claws you brought me. Use it to catch the shadow sturgeon in these coastal waters.", progress = "Catch those sturgeon?", completion = "I see you are both a fisherman and a warrior.  I will do what I can to help you.", objectives = "Prove your worth to Madari by catching 5 Shadow Sturgeon using the supplied bait.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36202] = { id = 36202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anglin' In Our Garrison", description = "You have proven your worth, traveler.  Now take this eventide fishing journal back to your garrison and study up.  You will be catching all you can eat in no time.", progress = "We can use that as bait?!", completion = "Look at all the bait ideas in this thing! Great job {name}!", objectives = "Return to Ron Ashton with the Eventide Fishing Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36203] = { id = 36203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Goren Egg" }
quests[36204] = { id = 36204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Gorger the Hungry" }
quests[36205] = { id = 36205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fractured Hammer", description = "It is obvious that this elaborate smithing hammer has seen better days.\n\nNow fractured and dirty, it is merely a shadow of its former self.\n\nOne thing is certain, its previous owner was neither ogre nor Iron Horde.\n\nPerhaps someone at Stonefang Outpost would know who this belongs to.", progress = "What do you want, {race}?", completion = "My father's hammer, where did you find this!?", objectives = "Search Stonefang Outpost for the hammer's previous owner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36206] = { id = 36206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dragon's Tale", description = "Chromie thinks she's picked up the trail. We suspect that Garrosh traveled through here when he first arrived on Draenor. But what about Kairoz? He must be close.\n\nChromie will illuminate the clues. Look for a series of temporal anomalies. Follow the trail east of here and pick your way up to the top of the mountains until we've located Kairozdormu... or his body. Good luck!", completion = "That solves one riddle. The moment they arrived in Draenor, Garrosh killed his savior.\n\nHe left the job unfinished; The dragon's spirit is still restless.\n\nI hope you're ready for a fight.", objectives = "Follow the trail of clues up the hillside until you discover Kairozdormu in the Time-Lost Glade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36207] = { id = 36207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waruk the Frostforger", description = "Many say my father was a legendary blacksmith, Waruk the Frostforger they called him. They will tell you tales of his mighty weapons, crafted with nothing more than ice and steel. Waruk the Lieforger, I call him.\n\nHe promised he wouldn't be gone long, \"I must support our troops!\" he said.\n\nWhy did he have to go? Why did they let him get captured!?\n\nI have no more need for broken tools than I do broken promises. His grave is east of here, you can leave this with the rest of his unwanted belongings.", progress = "Greetings {race}, what brings you to this old orc's grave?", completion = "Where did you find this hammer!?", objectives = "Deliver Waruk's hammer to his grave site.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36208] = { id = 36208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crystal Shard", description = "I'm glad you arrived when you did.\n\nThe Laughing Skull orcs practice some strange spirit magic, but one of their traditions could be quite useful in our situation.\n\nWhile I make preparations, can you gather the reagents?\n\nFirst, we'll need crystals from the husks of goren corpses. You can find their bodies in the canyon.", progress = "I have learned some of the Laughing Skull traditions. This is less strange than many.", completion = "Goren crystals are used by some as weapons. The acid left behind can be deadly though, even to the wielder.", objectives = "Collect 25 Goren Crystals from Longtooth Gorgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36209] = { id = 36209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Under There?", description = "It is done.\n\nWith this enchantment, not only can you roam amongst the goren freely, but you can move as they do.\n\nYour travels through the canyon are now made easier. You have safe access to places otherwise impossible to reach.\n\nPerhaps these tunnels will lead to more information that could be used against the Iron Horde.", progress = "That goren disguise smells awful.", completion = "Your search brought rewards?", objectives = "Use the goren disguise to explore locations in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36210] = { id = 36210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hard Shell", description = "I have already learned much from watching the Laughing Skull.\n\nTraveling through goren tunnels was thought to be impossible due to the acid they leave behind, but the orcs found a way around it.\n\nWe will need some of the shells of goren within the canyon.\n\nIf you see any of their tunnel craters ready to burst, approach them and goren will come pouring out. This way, you can kill many at once and find the shells more quickly.", progress = "Goren seem willing to eat anything in their path, alive or otherwise.", completion = "Ah, yes, these shells will work perfectly.", objectives = "Collect 9 Goren Shells from Boneyard Gorgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36211] = { id = 36211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Boots Bootstrap" }
quests[36212] = { id = 36212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Wrist Bootstrap" }
quests[36213] = { id = 36213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Ring Bootstrap" }
quests[36214] = { id = 36214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "6.0 Tanaan - Hands Bootstrap" }
quests[36219] = { id = 36219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nWho am I kidding, who wouldn't be interested in fame, fortune, and brawlin'? I'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you.", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36220] = { id = 36220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How Tough Are You?", description = "Mogor's holding a special match over at the Ring of Blood to crown the new Blood Champion and I think you have what it takes!\n\nNow, these ogres respect one thing and one thing only: badass...ness. They have a big fella at the front door making sure only the toughest gladiators enter the proving grounds.\n\nIf you're in, kill the grizzled gladiator Lug'dol at the tower just up the road and present his head to Kroggol the Wall. That oughta show 'em what you're made of.", progress = "Nobody gets in da proving grounds unless I say so.", completion = "If you kill Lug'dol, you definitely belong in da proving grounds.\n\nI don't even care that you tiny not ogre!", objectives = "Kill Lug'dol and present his head to Kroggol the Wall outside the Gorian Proving Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36221] = { id = 36221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entry Fee", description = "You looking for da Ring of Blood? HAH! That good one. Not just anybody able to compete in da ring. You gotta pay the entry fee: fifty blood marks.\n\nHow do you get them? Oh, tiny one, you killing me!\n\n<Kroggol hands you a small stone caked in blood.>\n\nDat one is yours. You kill others in da proving grounds to get da rest. Take dem to Wodin da troll servant by Mogor when you done.\n\nDon't talk to Mogor, though. Mogor da boss.", progress = "Don't be wastin' my time, {race}. What business do you be havin' with Mogor?", completion = "You? Fightin' ta be da Blood Champion? Hmm.", objectives = "Gather 50 Blood Stones and bring them to Wodin the Troll Servant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36222] = { id = 36222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion of Blood", description = "You have da blood stones required as proof of your worth. Hmm. Yes, you might be da champion Mogor be lookin' for.\n\nYou be one of only two to complete da blood stone trial. Da two of ya be fightin' for da glory of becoming Blood Champion.\n\nSpeak to Gurgthock and we be seein' if you be a champion... or just another stain on da arena floor.", progress = "Only da very best be havin' a chance at bein' da Blood Champion, mon.", completion = "You did it, mon! I never thought I'd be seein' such a fight!", objectives = "Speak to Gurgthock to participate in the Blood Champion fight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36223] = { id = 36223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Every Soldier Behind", description = "The ogron possess something of value to the Iron Horde. I am sure they're unaware, likely just bored and in need of something to torture.\n\nWe could simply leave them to their fate, but we should follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond's most fearsome creatures into weapons.\n\nTry to find Corporal Thukmar and his notes.", progress = "Again you've done well, friend.", completion = "We have the notes. Let us see what they reveal about our enemy's strategy.", objectives = "Find Corporal Thukmar and recover his intel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36226] = { id = 36226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Survey Ashran", description = "As a Farseer, I can peer into the far corners of Ashran while within Warspear. But you must go forth and see it for yourself, {name}.", completion = "You have the spirit of a true explorer, {name}.", objectives = "Farseer Mare Wildrunner in Warspear wants you to explore The Road of Glory, The Molten Quarry, Brute's Rise, The Amphitheater Of Annihilation and The Ashmaul Burial Grounds in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36227] = { id = 36227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Road of Glory", description = "THE ALLIANCE! <Stomps feet> THEY NEED TO BE REMOVED FROM ASHRAN IMMEDIATELY! MARCH INTO THE ROAD OF GLORY AND SLAY AS MANY AS YOU CAN! \n\nNOW!", completion = "ONLY FIVE? UGH. TAKE THIS REWARD AND GET BACK OUT THERE.", objectives = "Zurge in Warspear wants you to kill 5 members of the Alliance within the Road of Glory.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36228] = { id = 36228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into The Wilderness", description = "YOU KNOW WHAT'S BETTER THAN KILLING ALLIANCE SCUM IN THE ROAD OF GLORY?\n\nKILLING THEM EVERYWHERE ELSE. <Laughs>\n\nGO INTO THE OUTSKIRTS OF ASHRAN AND SLAY ANY ALLIANCE MEMBER. BRING ME BACK SCRAPS OF THEIR DISGUSTING ARMOR AS PROOF. THE BLOODIER THE BETTER.", progress = "SHOW ME THE ARMOR SCRAPS!", completion = "YES... YES! <Takes a deep whiff of the armor scrap> MMMM,  ITS FRESH!", objectives = "Zurge in Warspear Outpost wants you to kill a member of the Alliance outside of the main road and recover a piece of their armor as proof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36229] = { id = 36229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Vignette Boss - Mr. Pinchy Sr." }
quests[36230] = { id = 36230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Restless Spirit", progress = "So, it is done?", completion = "{name}, thank you for avenging my death.", objectives = "Slay Kurgthuk the Merciless and use Waruk's hammer to salvage equipment from the Thunderlord orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36236] = { id = 36236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cryptic Tome of Tailoring", description = "The different sections of the tome describe tailoring techniques that seem strange compared to traditional methods.\n\nThe author's name does not appear anywhere in the tome. Maybe someone in your garrison knows more about the book's origins.", progress = "What have you there, child?", completion = "It seems that you have found a very special tailoring book.\n\nIt belongs to Ameeka, a tailor of great renown from Embaari Village.", objectives = "Speak to Aerun in your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36238] = { id = 36238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mending A Broken Heart", progress = "My father... but, how did you....", completion = "This entire time... I have been so consumed with my own grief.\n\nI never once stopped to consider how much my father was suffering at the hands of our enemies.\n\nThank you so much, {class}, for helping him to return to me. Please, allow me to repair his hammer.\n\nIn exchange for everything you have done for us, I will teach you whatever you wish to know.", objectives = "Meet Waruk at Stonefang Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36239] = { id = 36239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Mysterious Satchel", description = "An empty satchel with an old, magical aura.\n\nIt appears quite dilapidated, with remnants of herbs and mushrooms along the inner lining. Perhaps exploring Umbrafen will offer a clue.", completion = "Oh, my. One of my satchels! Where did you find this? I lost it weeks ago.\n\nI've been so busy training I forgot to collect herbs for Master Ardule. I need your help {name}, if you are willing, but I must warn you - the herbs can be quite dangerous!\n\nHand me the satchel and I'll restore the protective inscription to guard you from harmful toxins.", objectives = "Find the satchel's owner.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36240] = { id = 36240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slow and Steady", description = "Excellent!\n\nWhen you've collected enough herbs from the local wildlife, return to me and I'll craft them into an ink for Master Ardule.\n\nThe sporebats and giants should have what you're looking for.\n\nAnd remember, be careful!", progress = "Ah, these are just what I was looking for!", completion = "That was fast, {name}! And such a generous delivery!\n\nI've secured the ink in a vial for you, but please be careful.", objectives = "Gather the herbs and return to Sha'la.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36241] = { id = 36241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power of Preservation", description = "The ink is very precious to our people. It has the ability to preserve ancient texts.\n\nMaster Ardule can explain further. He's just inside.", completion = "My, {name}. Your delivery...\n\nI don't know how to thank you enough.\n\nThis is a substantial amount of ink. You've helped ensure our history for generations to come.\n\nPerhaps I can repay you with a taste of the very knowledge you've helped preserve?", objectives = "Deliver the ink to Master Ardule.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36242] = { id = 36242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Where There Is Smoke...", description = "You garrison is under attack by the Burning Blade!\n\nKill the Burning Blade masters that are leading the assault and report back to Warmaster Zog.", completion = "I knew it was only a matter of time before Azuka would make her move.", objectives = "Kill Rag'sla Thunkblade, Akatha Blazeburn, and Drek the Firecaller.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36243] = { id = 36243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 001 - Outcast's Basket" }
quests[36244] = { id = 36244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 002 - Misplaced Scrolls" }
