quests[36248] = { id = 36248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Stolen Heart", description = "This invasion is clearly an attempt to seize the Heart of Gorgorek.\n\nWe need to fortify our guard before it's too late!", completion = "Azuka's reign of terror continues... we need a new plan.", objectives = "Defeat Azuka Bladefury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
