quests[36254] = { id = 36254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 002 - Tesska the Broken" }
quests[36255] = { id = 36255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Highmaul Bracer", description = "A powerful enchantment emanates from these ancient Highmaul bracers.\n\nMaybe Yu'rina the Mystic, your garrison enchanting quartermaster, can tell you more about the bracer.", completion = "Interesting, an Arakkoa recently visited the garrison looking for an armor piece with a powerful enchantment like this. His name was Delath.\n\nThe enchantment on this bracer is beyond my skill, but perhaps this Delath can give you the necessary insight to replicate it.", objectives = "Take the bracer to Yu'rina the Mystic in your Garrison.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36256] = { id = 36256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arakkoan Enchanter", description = "The arakkoa said it was going to investigate an anomaly in the Cracking Plains that might be related to another armor piece.", progress = "Greetings Enchanter. I can see you are acquainted with the art. \n\nGood, good. Perhaps you and I can help each other.", completion = "Do I also detect that you have in your possession an artifact of our land? \n\nCan I see it?\n\nOne of Oru'kai's bracers... Thank you!", objectives = "Find Delath on the edge of the Cracking Plains to the north.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36257] = { id = 36257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Failed Apprentice", description = "Oru'kai was the first ogre mage to master the art of enchanting. Upon his death, his items were scattered across Draenor. I have tracked his scepter to the field you see before us. \n\nAs you can see, the scepter's enchantment is making it difficult to retrieve. A would-be apprentice, Torag Stonefury, took one of Oru'kai's rings in to break the enchantment, but he failed and became trapped in ice. \n\nFree Torag, take the ring, and complete his task, and I will consider a reward.", completion = "Thank you. I thought I was going to be stuck here forever.", objectives = "Find and release Torag from his icy prison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36260] = { id = 36260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oru'kai's Scepter", description = "If I had known being an enchanter was this dangerous, I would have stayed in Wor'gol. \n\nHere, take this ring. The bird man told me to use the ring on the scepter to nullify the enchantment.\n\nBring the scepter back to him and maybe he will teach you what he promised to teach me.", progress = "Do you have it? Give it to me.", completion = "Yes... This is it, after so many years. Soon, I will have all of the Armaments of Oru'kai.\n\nReturn my ring as well and I will fulfill the promise I made to that squeamish orc. \n\nTake this book. If you have any skill, you can use it to decipher and learn Draenor's enchantments. \n\nOf course, you will need a proper workplace as well. Here are plans; hopefully you can follow them.\n\nNow, be gone, and steer clear of the other armaments, for they are mine.", objectives = "Retrieve Oru'kai's scepter and return it to Delath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36261] = { id = 36261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: Missing Grunt", description = "With the Heart of Gorgorek residing inside the garrison walls, we need to stay vigilant. The Burning Blade are known for attacking swiftly, and without warning.\n\nI have a number of grunts patrolling the keep. Dul'zak, one of our newer recruits, should have reported back by now.", objectives = "Find Dul'zak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36262] = { id = 36262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ameeka, Master Tailor", description = "Ameeka created this book to document and pass down our most cherished crafting techniques to our children. She must have dropped it while traveling. She will be relieved to see her book.\n\nFrom what I have heard from other villagers, she was last seen on the road to Elodor. Perhaps you can find her there.", progress = "Hello, traveler! Is there something that I can help you with?", completion = "Is that my tailoring tome? It is! I'm so glad it is safe! How can I ever repay you?", objectives = "Speak to Ameeka in Elodor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36263] = { id = 36263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strengthened Bond", description = "This entire time... I have been so consumed with my own grief.\n\nI never once stopped to consider how much my father was suffering at the hands of our enemies.\n\nThank you so much {class} for helping him to return to me. Please, allow me to repair his hammer.\n\nIn exchange for everything you have done for us, I will teach you whatever you wish to know.", objectives = "Give Axe-Shaper Kugra the Ghost-Touched Materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36265] = { id = 36265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 001 - Stonespite" }
quests[36266] = { id = 36266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Clothes on Their Backs", description = "Such kindness you have shown me, perhaps I can ask for one more?\n\nIn our village, we salvage and reuse old cloth to patch clothes and light armor. Sadly, most of my supply was taken or destroyed in the recent attacks.\n\nThe Shadowmoon cultists might think twice about stealing from us if you were to relieve them of their own resources.\n\nIf you can collect some ceremonial Shadowmoon robes for me, I will demonstrate some of my favorite tailoring techniques for you.", progress = "Were you able to get the robes?", completion = "Again, you show me great kindness.\n\nNow, let us begin.", objectives = "Collect 10 Ceremonial Shadowmoon Robes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36267] = { id = 36267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 005 - Durkath Steelmaw" }
quests[36268] = { id = 36268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 007 - Kalos the Bloodbathed" }
quests[36269] = { id = 36269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hexcloth", description = "I shall now impart to you the finer points of creating hexcloth.\n\nThe process is quite simple. It involves immersing carefully woven fur into the ichor drawn from Gorgrond Flytraps.\n\nNormally, you would need to harvest it yourself, but I actually managed to liberate some from the Shadowmoon during their last raid.\n\nYou are welcome to use it.", progress = "Were you successful, friend?", completion = "This is perfect! The cloth and magic are perfectly balanced and stable.\n\nI am happy to say that you have learned the basics of my tailoring methods. I respect your skill and your eagerness to learn new techniques.\n\nLet me give you some other patterns and materials that I hope you find useful during your journey.", objectives = "Use Ameeka's Flytrap Ichor to create a Swatch of Hexweave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36271] = { id = 36271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking into the Trap Game", description = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here.\n\nWe can get a load of leather from the elekk, or furs from the talbuk, right here in Shadowmoon.\n\nTake this iron trap and use it on a wounded adult talbuk or elekk, then bring the trap on back here and we'll start a work order.", progress = "Have you tried your hand at trapping yet?", completion = "Great job, commander! We'll have your leather or fur ready in no time.\n\nNow that you know how to use the trap, it will be available for your use at any time. We can only handle so many beasts in the barn at one time, though, so make sure you've got room before you start trapping!", objectives = "Use the Iron Trap to capture an Elekk or Talbuk in Shadowmoon Valley and then place a Work Order at your Barn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36272] = { id = 36272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding An Army", description = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one!\n\nMind giving 'er a run, commander? The Improved Iron Trap will let you capture some of the meatiest wildlife, like the big boars and riverbeasts out in Gorgrond. We'll be able to turn them into some tasty steaks.", progress = "Did ya try the trap out yet?", completion = "Great work, commander! We'll get to grillin' up those steaks right away. I can already smell them!", objectives = "Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36273] = { id = 36273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whacking Weeds", description = "Something needs to be done about the podling menace in Spiteleaf Thicket!\n\nAlongside Hemet Nesingwary, I've hunted some of the largest and most terrifying beasts around. Never in my life have I encountered a creature as vile, depraved, nefarious or degenerate as a podling!\n\nThe vicious little monsters spread themselves like weeds and if something isn't done, they'll spread across the entire continent!\n\nMake your way into Spiteleaf Thicket and slay as many podlings as you can find!", completion = "Great work, {name}.\n\nI'm surprised we made it out of Spiteleaf Thicket alive! I can still hear the sound of their maniacal laughter as they swarmed us....", objectives = "Slay 20 Spiteleaf podlings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36274] = { id = 36274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger Trap, Better Rewards", description = "Good news, commander! With the materials we've gathered here in Draenor, we've been able to construct a trap strong enough to immobilize even the mightiest beast!\n\nWhy don't you head on out to Nagrand and give it a try? Word has it that the western plains are home to some of the most magnificent beasts this side of Crystal Lake.\n\nI'm going to warn you, though, these beasts are tough. You may want to bring some friends along.", progress = "Well? How'd it go?", completion = "That must have been quite a fight, commander!\n\nThe materials we obtain from beasts of this magnitude will last us for quite a while.", objectives = "Use the Deadly Iron Trap to capture an Ironhide Bull, Direfang Alpha, or Wetland Trampler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36275] = { id = 36275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search For Research", description = "My research notes are missing!\n\nThey must have gone missing during the podling attack on the research station. All of my work will be lost if they are not found!\n\nCome to think of it, I'm also missing my expedition supply bag, as well as my anti-fungal boots....\n\nHow can I do biological research without my equipment?!\n\nNo... this will not do at all.\n\nPlease, go and search the Zangar Shore for my missing belongings so that I may continue my fungal research!", progress = "Have you retrieved my missing belongings?", completion = "Ah! I see you have my research with you... and what's this? You also have my supply bag and the anti-fungal boots!\n\nSpectacular! I now have the tools I need to continue my research into the Zangar fungal strain....", objectives = "Return the Research Journal, Expedition Supplies, and Anti-fungal Boots to Dr. Hadley Ricard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36276] = { id = 36276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 008 - Spawn of Sethe" }
quests[36277] = { id = 36277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlords Max Level Dungeon Bonus Reward Quest" }
quests[36278] = { id = 36278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 009 - Talonbreaker" }
quests[36279] = { id = 36279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette 010 - Poisonmaster Bortusk" }
quests[36280] = { id = 36280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nYou're the one that brought a new meaning to pain at the Ring of Trials not too long ago, right? This is the next step in your climb to fame! You've gotta get down here.\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you.", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36281] = { id = 36281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. I've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nIf you think the Stonemaul arena was a thrill, this is way, way bigger than that. It's going to be HUGE, I'm calling it now.\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you.", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36282] = { id = 36282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Ring of Blood", description = "Hey Champ,\n\nYou were out when I stopped by. You're the talk of the arena, friend! I mean, the Ring of Trials? Stonemaul? You're killing it out there!\n\nI've got a sweet gig set up at the Ring of Blood in Nagrand. Lots of ogres looking for the next big fight. Big money. You in?\n\nI'll meet you at my stash so we can talk a bit in private before your big debut.\n\n<A map is included with a dollar sign scrawled on an abandoned ogre tower.>", completion = "I won't waste your time, champ. I've got a once in a lifetime opportunity for you.", objectives = "Speak to Gurgthock at Gurgthock's Stash in Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36283] = { id = 36283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 011 - Blightglow" }
quests[36284] = { id = 36284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fascinating Fungus", description = "The Zangar Shore is home to many peculiar strains of fungi, some of which are similar to those of our native Azeroth. However, one strain in particular is most fascinating!\n\nI call it \"Zangarium Draenormycota,\" due to its prevelance in Draenor's fungal ecosystem. This unique strain of fungus is highly adaptable and can be found on many of the living organisms throughout Zangar Shore.\n\nWhy does it exist? What properties does it hold?\n\nTo answer these questions, I will need additional spore samples.", progress = "Have you collected the spore samples for my research?", completion = "You have the spore samples for my research! Excellent!\n\nThe Zangar Shore is a dangerous place... what with the risk of fungal mutation and all.\n\nOh... I didn't mention that part before? I was sure I did!\n\nNo matter! You look hardy enough, I'm sure your genes are impervious to foreign fungal strains that your body has never before encountered!", objectives = "Collect 12 Fungal Spores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36285] = { id = 36285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dirgemire", description = "In order to fully understand the nature and properties of the Zangarium Draenormycota, I need to examine the strain within a complex fungal structure. The fungal brain of a spore giant would do nicely.\n\nNot just any spore giant will serve though, it needs to be big... mean... primordial... the perfect specimen!\n\nIn a cavern deep below the surface is an ancient spore giant the locals fearfully refer to as Dirgemire. Slay the monster, but be sure to carefully preserve the fungal brain for our research!", progress = "Without a fungal brain to examine, the mysteries of the Zangar ecosystem will remain unsolved!", completion = "I see you've retrieved Dirgemire's fungal brain!\n\nNot only is the fungal structure perfectly intact, as a specimen it is exquisite! I will need only a moment to begin the examination...", objectives = "Retrieve the Fungal Brain from Dirgemire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36286] = { id = 36286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Transponder 047-B", description = "The back of the transponder is etched in scribbled writing.\n\n<URGENT: If found, please return to Goggles near Eledor. It is of the utmost importance!>", completion = "Oh my! What do we have here, commander?\n\n<Inspecting the transponder.>\n\nA little damaged, slightly bent and burnt to a crisp, but this is my lucky day!\n\nWe've been testing a new device and this transponder carries invaluable information! I'll have Bixx extract the coordinates for mapping.\n\nJust a few more parts and I should be able to teleport anything across this entire valley! And I do mean anything!\n\nThat'll surely help our reinforcements stand against the Iron Horde!", objectives = "Return the transponder to Goggles.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36287] = { id = 36287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snatch 'n' Grab", description = "We were able to map all of the data from the transponder you recovered! Now our location analyzer is complete!\n\nWe're just missing a few final pieces, then the real testing begins.\n\nOne of my pilots mentioned seeing a beached Iron Horde ship over by the shore. If you can salvage some parts we may just be able to get this thing up and running!", progress = "Don't worry. We're just borrowing these from the Iron Horde!", completion = "Those supplies were just what I needed! I think I'm finally figuring out how to work with all these Draenor parts. I'd be happy to show you, commander. I should be able to fix it in a jiffy.\n\nOh... and remember, deep breaths!", objectives = "Search the beach for salvageable parts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36288] = { id = 36288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 012 - Oskiira" }
quests[36289] = { id = 36289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Shadows", description = "Congratulations again, Blood Champion. You be fightin' like nobody I ever seen.\n\nWhile you were in da ring, one ayour bruddas came by and asked for you ta return ta your base. He called himself Bodrick Grey.", completion = "We'll need to keep an eye on this Azuka Bladefury character. Sounds dangerous.", objectives = "Speak to Bodrick Grey at your Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36290] = { id = 36290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Shadows", description = "Congratulations, Blood Champion. You be fightin' like nobody I ever seen.\n\nWhile you were in da ring, one a your bruddas came by and asked for you ta return ta your base. He called himself a shadow hunter.", completion = "We best be keepin' an eye on dis Azuka Bladefury. She be bad news.", objectives = "Speak to Rokhan in your Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36291] = { id = 36291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 014 - Betsi Boombasket" }
quests[36292] = { id = 36292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Invasion", description = "I'm going to lead a small squad behind enemy lines.\n\nMeet me by Dreadmaul, {class}. From there we can decide our next course of action.", completion = "Glad you made it, {name}. It's time to start pushing back on this Iron Horde invasion.", objectives = "Meet Thrall behind enemy lines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36293] = { id = 36293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Gotta Work!", description = "My apprentice Nubble was able to use your salvaged parts to put the finishing touches on the new location analyzer.\n\nHead on over to try out my newest invention!", objectives = "Visit Nubble.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36294] = { id = 36294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylarch the Evergreen A" }
quests[36295] = { id = 36295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylarch the Evergreen B" }
quests[36296] = { id = 36296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Phylarch the Evergreen", description = "[PHYLARCH ACQUISITION TEXT GOES HERE]", completion = "For tens of thousands of years we Botani have clashed against the mightiest forces of this world, but none have had your unbridled ferocity and resilience.\n\nI... I concede to your battle prowess. I will aid you in your campaign for dominance of my world.\n\nIf you will accept me.", objectives = "Accept the Blood Oath of Blademaster Na'Shra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36297] = { id = 36297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 016 - Festerbloom" }
quests[36298] = { id = 36298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 017 - Sunderthorn" }
quests[36301] = { id = 36301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trega's Tailoring Kit", description = "The bag is filled with patterns and unfamiliar tailoring tools. You find the name \"Trega\" embroidered on the inside of the bag.\n\nYou seem to recall seeing her in Wor'gol. With any luck, she's still there.", progress = "That's my sewing kit! I never thought I would see this again.", completion = "I was chased by ogres and had to leave my bag behind. It looks like almost everything is here, except for... oh, no!", objectives = "Find Trega in Wor'gol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36303] = { id = 36303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 019 - Eyeless" }
quests[36304] = { id = 36304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 022 - Gochar" }
