quests[36307] = { id = 36307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Investigating the Invasion", description = "I'm going to lead a small squad behind enemy lines.\n\nMeet me by Dreadmaul, {class}. From there we can decide our next course of action.", completion = "Glad you made it, {name}. It's time to start pushing back on this Iron Horde invasion.", objectives = "Meet Maraad behind enemy lines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36308] = { id = 36308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Highmaul Bracer", description = "A powerful enchantment emanates from these ancient Highmaul bracers.\n\nMaybe Eileese Shadowsong, your garrison enchanting quartermaster, can tell you more about the bracer.", completion = "Interesting, an Arakkoa recently visited the garrison looking for an armor piece with a powerful enchantment like this. His name was Delath.\n\nThe enchantment on this bracer is beyond my skill, but perhaps this Delath can give you the necessary insight to replicate it.", objectives = "Take the bracer to Eileese Shadowsong in your Garrison.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36309] = { id = 36309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Strength of Iron", description = "A stitched patch along the side of the satchel clearly identifies its owner.\n\nYou remember hearing stories of a great blacksmith just north of Embaari.", completion = "This... this is my satchel... but how?\n\nDid you see a boy - a young boy near this? You must tell me where you found it!\n\nI tried to fight them, but the looters... they were too strong! They almost killed me!\n\nPlease, please....\n\nI'd give anything to have my only son back! I cannot fail him....", objectives = "Deliver the satchel to Haephest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36310] = { id = 36310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arakkoan Enchanter", description = "The arakkoa said it was going to investigate an anomaly along the Forgotten Shore that might be related to another armor piece.", progress = "Greetings Enchanter. I can see you are acquainted with the art. \n\nGood, good. Perhaps you and I can help each other.", completion = "Do I also detect that you have in your possession an artifact of our land? \n\nCan I see it?\n\nOne of Oru'kai's bracers... Thank you!", objectives = "Find Delath on the Forgotten Shore to the south.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36311] = { id = 36311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Father and Son", description = "Please find my boy!\n\nBefore the looters came we were on the hill just northeast of here.\n\nThere weren't many of them, but I'm a blacksmith, not a fighter!\n\nHave I let my only son down?", completion = "My boy!\n\n<A tear falls down his cheek, clearing a path down to the skin where soot once rested.>\n\nYou... no words can explain how grateful I am.\n\nI can only repay what I have to offer, which isn't much in terms of valued goods. Most of my work goes straight to our soldiers.  I do, however, carry the wisdom of my people and my craft.\n\nIt would be an honor if you allowed me to share some of this wisdom with you.\n\nMay the light guide you, {name}.", objectives = "Find Haephest's son.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36312] = { id = 36312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Vignette Boss 025 - Sun Sage Valarik" }
quests[36313] = { id = 36313, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Failed Apprentice", description = "Oru'kai was the first ogre mage to master the art of enchanting on Draenor. Upon his death, his items were scattered across Draenor. I have tracked his staff to the shore you see before us. \n\nAs you can see, the staff's enchantment is making it difficult to retrieve. A would-be apprentice, Deema, took one of Oru'kai's rings in to break the enchantment, but she failed and became trapped as well. \n\nFind and free Deema, take the ring, complete her task, and I will consider a reward.", completion = "Thank you. I thought I was going to be stuck here forever.", objectives = "Find and release Deema from her time prison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36314] = { id = 36314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Intricate Pendant", description = "The crimson gem used in this pendant is unlike any you've seen before, and the filigree wrapped around it is masterfully crafted.\n\nThere's likely to be much you can learn from the person who made this. Perhaps someone at your garrison will recognize the work.", progress = "Why hello {name}, what do we have here?", completion = "Please, allow me to take a closer look.", objectives = "Ask around your garrison to see if anyone recognizes the pendant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36315] = { id = 36315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oru'kai's Staff", description = "If I had known being an enchanter was this dangerous, I would have stayed in Shattrath. \n\nHere, take this ring. The arakkoa told me to use the ring on the staff to nullify the enchantment.\n\nBring the scepter back to him and maybe he will teach you what he promised to teach me.", progress = "The staff! Give it to me!", completion = "Yes... This is it, after so many years. Soon, I will have all of the Armaments of Oru'kai.\n\nReturn my ring as well and I will fulfill the promise I made to that squeamish draenei. \n\nTake this book. If you have any skill, you can use it to decipher and learn Draenor's enchantments. \n\nOf course, you will need a proper workplace as well. Here are plans; hopefully you can follow them.\n\nNow, be gone, and steer clear of the other armaments, for they are mine.", objectives = "Retrieve Oru'kai's staff and return it to Delath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36316] = { id = 36316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Victory is Within Reach", description = "We have dealt a crippling blow to the Adherents, but our fight is not yet finished.\n\nGather your allies and prepare for the final siege on Skyreach!\n\n\"Shadows gather when the raven swallows the day.\n\nBurning sky is extinguished as black wings fold gently about the heavens.\n\nRest, my children, rest. For even the sun must sleep.\"\n\nThis was Rukhmar's lullaby, sung by her to the first arakkoa. My, how we've lost our way.", progress = "Let us finish what we have started.", completion = "Perhaps there is now hope for a brighter future. I can only hope some of those in Skyreach have been awakened.", objectives = "Slay Ranjit, Araknath, Rukhran and High Sage Viryx in the Skyreach dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36317] = { id = 36317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ogre Arena Entrance Bridge" }
quests[36318] = { id = 36318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Hanging Alliance Platform" }
