quests[36340] = { id = 36340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 058 - Ogron Plunder" }
quests[36341] = { id = 36341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Fury", description = "It looks like this is it, commander.\n\nWe must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Bodrick Grey to deploy your troops to the Gates of Tanaan at once.\n\nBy the time you get to northern Talador, he should be waiting for you... with an entire army.\n\nThere is no time to delay.", completion = "Your feats seem to know no limits, {name}. Today, our garrison forces have struck a terrible blow to Warchief Hellscream and the Iron Horde.\n\nHowever, he is not defeated so easily. If anything, his hunger for vengeance will grow.\n\nWe must destroy the root of his operations in Tanaan Jungle, but first, there is much preparation to be done.\n\nUntil then, bask in the glow of our momentous victory.", objectives = "Meet Bodrick Grey near the Gates of Tanaan in Talador, then defeat Gorgorek and Warlord Azuka Bladefury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36342] = { id = 36342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal Fury", description = "It looks like this is it, commander.\n\nWe must stop the Iron Horde at all costs. I have sent stormcrows to your garrison, and called for Shadow Hunter Rokhan to deploy your troops to the Gates of Tanaan at once.\n\nBy the time you get to northern Talador, he should be waiting for you... with an entire army.\n\nThere is no time to delay.", completion = "Your feats seem to know no limits, {name}. Today, you and your garrison forces have struck a terrible blow to Warchief Hellscream and the Iron Horde.\n\nHowever, he is not defeated so easily. If anything, his hunger for vengeance will grow.\n\nWe must destroy the root of his operations in Tanaan Jungle, but first, there is much preparation to be done.\n\nUntil then, bask in the glow of our momentous victory.", objectives = "Speak to Shadow Hunter Rokhan in northern Talador, then defeat Gorgorek and Warlord Azuka Bladefury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36344] = { id = 36344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feeding An Army", description = "We've had a chance to work with these beasts for a while now, and that's allowed us to develop a brand-new trap for you to try out. It should be much sturdier than the last one.\n\nThe Improved Iron Trap will let you capture some of the meatiest beasts on Draenor. You will find that a single riverbeast or boar from Gorgrond can feed many warriors.\n\nTrap one and bring it back, and we will cook you a savage meal.", progress = "Did you try the trap out yet?", completion = "Ah, so the trap held! I can smell the meat already. This will make a great feast for our warriors!", objectives = "Use the Improved Iron Trap to capture a Boar or Riverbeast in Gorgrond and then place a Work Order at your Barn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36345] = { id = 36345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking into the Trap Game", description = "When we came through the portal, we weren't able to bring any of our animals with us. For us to produce leather and furs, we'll need to trap some of the native beasts and bring them back here.\n\nAlthough the plains are frozen, there are many clefthooves and wolves in Frostfire. We can gather leather from the clefthooves, or furs from the wolves.\n\nTake this iron trap and use it on a wounded adult beast. Bring the trapped creature back to us, and we will begin our work.", progress = "Have you tried your hand at trapping yet?", completion = "Very good. We will have your leather or fur ready soon.\n\nNow that you know how to use the trap, it will be available for your use at any time. We can only handle so many beasts in the barn at one time, though. I would not advise taking more from the land than necessary.", objectives = "Use the Iron Trap to capture a Clefthoof or Wolf in Frostfire Ridge and then place a Work Order at your Barn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36346] = { id = 36346, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bigger Trap, Better Rewards", description = "Ah, commander, it is good to see you again. With the materials we have gathered here in Draenor, we have been able to construct a trap strong enough to immobilize even the mightiest beast.\n\nThese enormous creatures can be found on the western side of Nagrand, among the most fertile plains.\n\nA word of warning: these beasts are great and powerful. You may want to bring some friends along.", progress = "Did you manage to break one of the great beasts?", completion = "Blood and thunder, that must have been quite a battle!\n\nThe materials we obtain from beasts of this magnitude will last us for quite a while.", objectives = "Use the Deadly Iron Trap to capture a Ironhide Bull, Direfang Alpha, or Wetland Trampler.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36347] = { id = 36347, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Socrethar's Rise" }
quests[36348] = { id = 36348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on Socrethar's Rise" }
quests[36352] = { id = 36352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Locating the Lapidarist", description = "Are you sure I can't take this off your hands? I'll give you a fair price!\n\nAlright, alright... if you insist on finding the owner, you might want to try visiting Wor'gol.\n\nRumor has it there is a master craftsman there who's skilled in manipulating precious metals and stones. Might be your guy.", completion = "{race}, how can I repay you for returning this pendant to me?", objectives = "Search for the owner of the pendant in Wor'gol.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36353] = { id = 36353, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Old Times' Sake", objectives = "{name}, we've been through hell and back together more times than I can count. You're the Alliance's best chance at defeating the Iron Horde, and you know it.\n\nHow do you feel about me joining your garrison? We can bring the fight to orcish scum together, just like old times.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
