quests[36358] = { id = 36358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Father and His Son", description = "We must hurry before more orcs arrive! My father works just down this path!\n\nWe'll be safe at his shop.", objectives = "Return Duna and the toolset to Haephest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
