quests[36368] = { id = 36368, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lumberjack", description = "All o' them mole machines got mighty unreliable here in Gorgrond. I hear tell that one of 'em might've crashed here in Tangleheart.\n\nSee if you can find Frenna. She would've been on the one we tracked to this location. I'll go lookin' for the mole machine to see if it can be repaired.", completion = "Frenna didn't make it out of Tangleheart.", objectives = "Find Frenna within Tangleheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
