quests[36376] = { id = 36376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren Invasion!", description = "Quakes have been shaking the garrison, and our scouts haven't reported in hours.", progress = "We must hold the line!", completion = "We sent them packing, Commander!", objectives = "Repel the goren invasion.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36377] = { id = 36377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Treasure 049 - Rukhmar's Image" }
quests[36378] = { id = 36378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Pressure, No Diamonds", description = "You wish to understand the secrets of our gems, {race}? In exchange for returning my pendant, I am willing to help.\n\nI must warn you, however, that the materials will not be easy to obtain.\n\nTo the north, you will find magma pools that give birth to living lava creatures. Contained within these, you may find magnificent diamonds.\n\nPlease return to me with a few of these diamonds...", progress = "Have you obtained the materials I asked for?", completion = "This diamond is marvelous! I shiver at the mere thought of the massive creature this must have come from...", objectives = "Acquire Lava Diamonds from the Lava Slimes that reside in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36379] = { id = 36379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peeking into the Portal", description = "I sent Scout Pazerp to get a better look at the portal. She should have reported back by now; what could be taking her so long?\n\nShe is one of my best scouts, I hope she is alright.", completion = "Poor Pazerp... this news is unsettling to say the least. The Iron Horde seems to have an unending supply of troops.", objectives = "Find Scout Pazerp and use her telescope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36380] = { id = 36380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diamonds Are Forever", description = "Please watch closely {name}. I shall craft this jewel into a fine pendant for you.\n\nHopefully you will learn a bit of true jewelcrafting in the process.", progress = "It is finished, and even more beautiful than the last!", completion = "Thank you for your help {name}, please take this pendant along with a copy of my research.\n\nI hope these will prove useful in helping you to better understand the secrets of Draenic gems.\n\nUntil we meet again, friend.", objectives = "Wait for Orolak to finish crafting the pendant.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36381] = { id = 36381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spires - Shrine Treasure 01 - Gift of Anzu" }
quests[36382] = { id = 36382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peeking into the Portal", description = "I sent Scout Pazaztick to be gettin' a better look at da portal. He shoulda reported back by dis time; what be taking him so long?\n\nDis is what happens when you hire da goblins as help.", completion = "Dis not good. Them Iron Horde be causin' a lot of da trouble round here. We need ta find a way ta deal wit dim.", objectives = "Find Scout Pazaztick and use her telescope.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36383] = { id = 36383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assault on the Pit", description = "The Iron Horde are stockpiling their weapons and ammunition outside of the Foundry. Their campaign throughout Draenor has left their caches vulnerable. Get in there and cause as much chaos as you can, and while you're at it use some of that ammunition against them if they're just going to leave it lying around!", objectives = "Destroy Iron Horde weapons cache and take out as many of them as you can.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36384] = { id = 36384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Trial", description = "Look, I didn't tell Kimzee about this because I don't want to hurt her feelings, I chose not to leave Pinchwhistle Point.\n\nSee, I've been working on a serum that I think should be able to cure the infected, but when I tried to test it I got surrounded and I injured my leg during the escape.\n\nI know I'm on the right track but I need to test it. Do me a favor and take this vial and go try it out on one of the infected outside.", progress = "Have you completed the field test, {name}?", completion = "The serum did what!??!\n\nI must have used too much growth hormone. Possibly... the mixture just needs to be shaken prior to dosage?", objectives = "Venture into Pinchwhistle Point and use the Vial of Untested Serum on an Infected Bruiser or Infected Lumberjack. Return to Krixel Pinchwhistle to report the results.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[36385] = { id = 36385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Ancients", description = "Opening the ancient tome you see that it's not actually a tome at all, but a container. Inside are four empty slots.\n\nUpon closer inspection each slot has next to it a carving of what appears to be a unique Draenor ancient, some glyphs and a receptacle used to hold a piece of the pictured ancient. There also appear to be directions to where these ancients may be found: medium timber -- Shadowmoon, Gorgrond, the Spires of Arak and Nagrand.\n\nThese are assassination instructions. From trees to kill trees.", progress = "What have you got there, commander?", completion = "So what you're saying is that this here book is actually a container to hold the remains of targets on a hit list? And the assassination was being perpetrated by another... tree?\n\nThis world is crazy.\n\nNow let's see what happens when we put all the pieces into place.", objectives = "Collect the Heart of Kuruk, the Trunk of Autuk, the Twig of Loruk, and the Roots of Hanuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
